    public static void main(String[] args) {
        String literal1 = "abc";
        String literal2 = "abc";
        String created = new String("abc");
        String compileTime = "ab" + "c";

        String part = "ab";
        String runTime = part + "c";

        System.out.println("literal == literal    : " + (literal1 == literal2));
        System.out.println("literal == new String : " + (literal1 == created));
        System.out.println("literal == \"ab\"+\"c\"   : " + (literal1 == compileTime));
        System.out.println("literal == part+\"c\"   : " + (literal1 == runTime));
