        System.out.println(literal1.equals(created));
        System.out.println(literal1.equals(runTime));
    }
}

public class Main {
    static void compare(String a, String b) {
        int r = a.compareTo(b);
        String order = r < 0 ? "前" : r > 0 ? "後" : "同じ";
        System.out.println(a + " は " + b + " より " + order + "（" + r + "）");
    }

    public static void main(String[] args) {
        compare("apple", "banana");
        compare("banana", "apple");
        compare("x", "x");
        compare("Java", "java");        // 大文字が前
        compare("abc", "abcd");
    }
}

