public class Main {
    static String capitalize(String s) {
        return s.substring(0, 1).toUpperCase() + s.substring(1);
    }

    public static void main(String[] args) {
        System.out.println(capitalize("java"));
        System.out.println(capitalize("silver"));
        System.out.println(capitalize("a"));        // 1文字でも動く
        System.out.println(capitalize("Java"));     // すでに大文字でもそのまま
    }
}

public class Main {
    public static void main(String[] args) {
        String[] words = {"java", "silver", "go"};

        int total = 0;
        String longest = words[0];

        for (String w : words) {
            System.out.println(w + " " + w.length());
            total += w.length();
            if (w.length() > longest.length()) {
                longest = w;
            }
        }

        System.out.println("合計 " + total);
        System.out.println("最長 " + longest);
    }
}

